describe('Countdown Timer Interval Update', () => {
  beforeEach(() => {
    cy.visit('/countdown');
  });

  it('should update countdown timer every second', () => {
    // Verify initial countdown value is displayed
    cy.get('[data-testid="countdown-timer"]').should('contain', '10');
    cy.get('[data-testid="timer-label"]').should('contain', 'seconds');

    // Wait for the first second to pass
    cy.wait(1100);

    // Verify timer has decremented by one
    cy.get('[data-testid="countdown-timer"]').should('contain', '9');

    // Wait for another second
    cy.wait(1050);

    // Verify timer has decremented again
    cy.get('[data-testid="countdown-timer"]').should('contain', '8');

    // Verify timer label remains visible
    cy.get('[data-testid="timer-label"]').should('be.visible');
  });

  it('should handle interval reset when timer reaches zero', () => {
    // Set initial countdown to 3
    cy.get('[data-testid="countdown-input"]').clear().type('3');
    cy.get('[data-testid="start-button"]').click();

    // Wait for first second
    cy.wait(1100);
    cy.get('[data-testid="countdown-timer"]').should('contain', '2');

    // Wait for second second
    cy.wait(1050);
    cy.get('[data-testid="countdown-timer"]').should('contain', '1');

    // Wait for third second (timer reaches zero)
    cy.wait(1050);
    cy.get('[data-testid="countdown-timer"]').should('contain', '0');

    // Verify timer is reset and ready to restart
    cy.get('[data-testid="countdown-timer"]').should('contain', '0');
    cy.get('[data-testid="start-button"]').should('be.visible');
    cy.get('[data-testid="reset-button"]').should('be.visible');
  });
});
